-- L10-PERS-personality.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   1 Which character are you quiz (8 questions, 6 character profiles): the eight questions of a series are rows of personality_questions at ord = group id * 12 + 1 to 8,
--         its profiles are rows of personality_profiles with their character_id. The page /which-{series}-character-are-you and the link on the series hub
--         exist for a series as soon as its rows are there; a set marked draft is loaded inactive (the page answers 404).
-- Needs:  L04, 002a, 013.
-- Verify: select count(*) from public.personality_profiles where site_id = 'anime';   expect 6
-- Undo:   L10-PERS-personality.rollback.sql (readers' saved results stay: they are rows of personality_results, which this file never touches).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if (select count(*) from public.groups where site_id = 'anime' and slug in ('death-note')) <> 1 then
    raise exception 'L10: the series groups are missing (apply L04 first)';
  end if;
end $o1l$;

do $o1l$ begin
  if (select count(*) from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug in ('light-yagami', 'l', 'ryuk', 'soichiro-yagami', 'touta-matsuda', 'kanzo-mogi')) <> 6 then
    raise exception 'L10: the characters of death-note are missing (apply L04 first)';
  end if;
end $o1l$;

do $k1p$
begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'personality_profiles' and column_name = 'character_id') then
    raise exception 'personality: personality_profiles.character_id is missing (apply SQL 013 first)';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'personality_questions' and column_name = 'site_id') then
    raise exception 'personality: personality_questions.site_id is missing (apply SQL 002a first)';
  end if;
end
$k1p$;

do $k1p$
begin
  if (select id from public.groups where slug = 'death-note' and site_id = 'anime') is null then raise exception 'personality: no group death-note on the anime site (load the series first)'; end if;
  if (select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 12 > 32767 then raise exception 'personality: group id of death-note is too large for the question band (ord is a smallint)'; end if;
  if exists (select 1 from public.personality_questions where ord between (select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 1 and (select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 12 and site_id <> 'anime') then raise exception 'personality: a question of another site sits in the band of death-note'; end if;
end
$k1p$;

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 1), 'A black notebook drops onto your desk and nobody saw it land. What do you do?', '[{"text":"Read every page twice before deciding anything","weights":{"energy":1,"chaos":0,"craft":5}},{"text":"Wave it around and tell the whole class","weights":{"energy":5,"chaos":4,"spotlight":0}},{"text":"Hand it to the nearest grown-up and let them sort it out","weights":{"chaos":0,"care":0,"heart":5}},{"text":"Poke it, shrug, and go find a snack","weights":{"energy":1,"chaos":5,"craft":1}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 2), 'How do you like to solve a hard problem?', '[{"text":"Alone, late at night, with a plan on paper","weights":{"energy":1,"craft":5,"spotlight":4}},{"text":"Out loud, with a crowd, thinking as I talk","weights":{"energy":5,"care":4,"spotlight":1}},{"text":"Step by step, by the book","weights":{"chaos":0,"craft":2,"heart":4}},{"text":"By trying silly things until one of them works","weights":{"energy":3,"chaos":5,"craft":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 3), 'Your friends cannot agree what to do on Saturday. You:', '[{"text":"Decide for everyone and make it sound obvious","weights":{"energy":4,"heart":2,"spotlight":0}},{"text":"Suggest something unexpected just to see what happens","weights":{"energy":3,"chaos":5}},{"text":"Say little, then quietly book the thing everyone half agreed on","weights":{"energy":0,"care":0,"spotlight":5}},{"text":"Ask each person what they actually want","weights":{"energy":3,"care":0,"heart":3}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 4), 'Which snack table is yours?', '[{"text":"A tidy lunch, eaten on time","weights":{"chaos":0,"care":0,"craft":2}},{"text":"Sweets. Many. All day","weights":{"energy":1,"chaos":4,"craft":4}},{"text":"Whatever my friends are sharing","weights":{"energy":4,"chaos":3,"care":5}},{"text":"An apple. Always an apple","weights":{"energy":1,"chaos":5,"spotlight":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 5), 'Someone you trust turns out to have lied to you. What happens next?', '[{"text":"I work out exactly why, then decide what it costs them","weights":{"chaos":0,"craft":4,"heart":1}},{"text":"I tell them straight away that I know","weights":{"energy":3,"heart":5,"spotlight":0}},{"text":"I laugh it off and ask for the full story","weights":{"energy":4,"chaos":5,"care":4}},{"text":"I go quiet and keep my distance for a while","weights":{"energy":0,"care":1,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 6), 'Pick the reputation you would like:', '[{"text":"The sharpest mind in the building","weights":{"craft":5,"heart":3,"spotlight":0}},{"text":"The one everyone likes immediately","weights":{"energy":5,"chaos":3,"care":5}},{"text":"The one you can trust with anything","weights":{"chaos":0,"care":0,"heart":5}},{"text":"The one nobody quite understands","weights":{"chaos":4,"craft":4,"spotlight":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 7), 'A lazy Sunday. Where are you?', '[{"text":"Perched on a chair, deep in a case file of my own invention","weights":{"energy":0,"chaos":3,"craft":5}},{"text":"Out and about, talking to someone new","weights":{"energy":5,"care":3,"spotlight":1}},{"text":"Watching the world from a rooftop, mildly bored","weights":{"energy":1,"chaos":5,"spotlight":5}},{"text":"Helping out at home, then a proper dinner","weights":{"chaos":0,"care":0,"heart":4}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

insert into public.personality_questions (ord, question, options, active, site_id) values (((select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 8), 'Someone offers you a shortcut to everything you want. You:', '[{"text":"Read the fine print, then probably take it","weights":{"chaos":0,"craft":4,"heart":0}},{"text":"Say no and keep doing it the slow way","weights":{"chaos":0,"care":0,"heart":5}},{"text":"Ask what the catch is, and whether it is funny","weights":{"chaos":5,"craft":3,"heart":3}},{"text":"Take it, share it, and hope it works out for everyone","weights":{"energy":4,"chaos":4,"care":5}}]'::jsonb, true, 'anime') on conflict (ord) do update set question = excluded.question, options = excluded.options, active = excluded.active where personality_questions.site_id = 'anime';

delete from public.personality_questions where site_id = 'anime' and ord between (select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 9 and (select id from public.groups where slug = 'death-note' and site_id = 'anime') * 12 + 12;

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Light Yagami', 'light-yagami', null, '{"energy":50,"chaos":0,"care":50,"craft":75,"heart":30,"spotlight":20}'::jsonb, array['You have a plan, a backup plan, and a calm face for the moment neither works.', 'People see the top of the class. You are already thinking three moves ahead.', 'You get restless when nothing is hard enough to hold your attention.']::text[], 1, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'light-yagami')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'L', 'l', null, '{"energy":10,"chaos":70,"care":60,"craft":95,"heart":85,"spotlight":90}'::jsonb, array['You think best crouched on a chair, a sweet in one hand and a theory in the other.', 'You say little, notice everything, and trust your own odd methods over anyone''s advice.', 'You would rather be right than popular, and you rarely need to choose.']::text[], 2, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'l')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Ryuk', 'ryuk', null, '{"energy":35,"chaos":85,"care":75,"craft":35,"heart":80,"spotlight":50}'::jsonb, array['You are here for the entertainment, and you are honest about it.', 'Rules bore you, drama delights you, and an apple fixes most afternoons.', 'You watch from the edge of the room and step in when it gets interesting.']::text[], 3, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'ryuk')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Soichiro Yagami', 'soichiro-yagami', null, '{"energy":65,"chaos":5,"care":0,"craft":45,"heart":90,"spotlight":45}'::jsonb, array['You are the one people lean on, and you carry it without a word of complaint.', 'You say what you mean, do what you said, and check on everyone before you sit down.', 'Right is right to you, even when it costs you a night of sleep.']::text[], 4, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'soichiro-yagami')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Touta Matsuda', 'touta-matsuda', null, '{"energy":85,"chaos":65,"care":75,"craft":35,"heart":40,"spotlight":50}'::jsonb, array['You walk in smiling and the room gets lighter.', 'You ask the question everyone else was too proud to ask, and you learn faster for it.', 'You may be the newest person on the team, but you make it feel like a team.']::text[], 5, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'touta-matsuda')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

insert into public.personality_profiles (group_id, member_name, member_slug, photo_url, axes, trait_lines, ord, active, site_id, character_id) values ((select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Kanzo Mogi', 'kanzo-mogi', null, '{"energy":10,"chaos":15,"care":10,"craft":55,"heart":75,"spotlight":90}'::jsonb, array['You say the least in the room and notice a lot.', 'You turn up early, do the job properly, and never need a thank you.', 'People forget you are there, then realise you were holding things together.']::text[], 6, true, 'anime', (select id from public.characters where group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and slug = 'kanzo-mogi')) on conflict (group_id, member_slug) do update set member_name = excluded.member_name, photo_url = null, axes = excluded.axes, trait_lines = excluded.trait_lines, ord = excluded.ord, active = excluded.active, site_id = excluded.site_id, character_id = excluded.character_id where personality_profiles.site_id = 'anime';

delete from public.personality_profiles where site_id = 'anime' and group_id = (select id from public.groups where slug = 'death-note' and site_id = 'anime') and member_slug not in ('light-yagami', 'l', 'ryuk', 'soichiro-yagami', 'touta-matsuda', 'kanzo-mogi');
